// Reads ChargeAutomation for the PMS. Read-only: only the GET paths below are
// allowed, so the app can never charge, refund, release a deposit or change a
// booking. The client id and secret come from n8n Variables
// CHARGEAUTOMATION_API_KEY and CHARGEAUTOMATION_API_SECRET; the access token
// (valid 24 hours) is kept in this workflow's static data between runs.
const BASE = 'https://api.chargeautomation.com';
const body = $json.body || {};
const path = typeof body.path === 'string' ? body.path : '';
const query = body.query && typeof body.query === 'object' && !Array.isArray(body.query) ? body.query : {};

const ALLOWED = [
  { pattern: /^\/api\/v1\/booking\/\d{1,20}$/, keys: [] },
  { pattern: /^\/api\/v1\/bookings$/, keys: ['property_id', 'status', 'from', 'to', 'created_from', 'created_to', 'page', 'page_size', 'sort_order'] },
  { pattern: /^\/api\/v1\/verify-payment-request\/[A-Za-z0-9_-]{1,100}$/, keys: [] },
];
const rule = ALLOWED.find((r) => r.pattern.test(path));
const badKey = rule && Object.keys(query).find((key) => !rule.keys.includes(key));
if (!rule || badKey) {
  return [{ json: { ok: false, status: 400, error: rule ? 'Query parameter not allowed: ' + badKey : 'Path not allowed: ' + path } }];
}

const clientId = $vars.CHARGEAUTOMATION_API_KEY;
const clientSecret = $vars.CHARGEAUTOMATION_API_SECRET;
if (!clientId || !clientSecret) {
  return [{ json: { ok: false, status: 500, error: 'Add the n8n Variables CHARGEAUTOMATION_API_KEY and CHARGEAUTOMATION_API_SECRET.' } }];
}

const store = $getWorkflowStaticData('global');
const tokenOf = (reply) => {
  const b = reply && typeof reply === 'object' ? reply : {};
  const d = b.data && typeof b.data === 'object' ? b.data : {};
  const access = b.access_token || d.access_token;
  if (!access) return null;
  const seconds = Number(b.expires_in || d.expires_in) || 86400;
  return { access, refresh: b.refresh_token || d.refresh_token || null, expiresAt: Date.now() + (seconds - 300) * 1000 };
};
const post = (url, payload) =>
  this.helpers.httpRequest({ method: 'POST', url, body: payload, json: true, returnFullResponse: true, ignoreHttpStatusErrors: true, timeout: 30000 });

async function login() {
  // A refresh token avoids sending the secret; fall back to the secret if it fails.
  if (store.caRefresh) {
    const refreshed = await post(BASE + '/api/v1/oauth/token/refresh', { refresh_token: store.caRefresh });
    const token = refreshed.statusCode < 400 ? tokenOf(refreshed.body) : null;
    if (token) return token;
  }
  const reply = await post(BASE + '/api/v1/oauth/token', { client_id: clientId, client_secret: clientSecret });
  const token = reply.statusCode < 400 ? tokenOf(reply.body) : null;
  if (!token) throw new Error('ChargeAutomation login failed (HTTP ' + reply.statusCode + '). Check the client id and secret in n8n Variables.');
  return token;
}
async function accessToken(force) {
  if (!force && store.caAccess && store.caExpiresAt > Date.now()) return store.caAccess;
  const token = await login();
  store.caAccess = token.access;
  store.caRefresh = token.refresh || store.caRefresh || null;
  store.caExpiresAt = token.expiresAt;
  return token.access;
}

const qs = Object.entries(query)
  .map(([key, value]) => encodeURIComponent(key) + '=' + encodeURIComponent(String(value)))
  .join('&');
const get = async (force) =>
  this.helpers.httpRequest({
    method: 'GET',
    url: BASE + path + (qs ? '?' + qs : ''),
    headers: { Accept: 'application/json', Authorization: 'Bearer ' + (await accessToken(force)) },
    json: true,
    returnFullResponse: true,
    ignoreHttpStatusErrors: true,
    timeout: 30000,
  });

let response = await get(false);
// Expired or revoked token (401, or ChargeAutomation's 1004): log in again once.
if (response.statusCode === 401 || (response.body && Number(response.body.status_code) === 1004)) response = await get(true);
return [{ json: { ok: response.statusCode < 400, status: response.statusCode, path, data: response.body ?? null } }];
